package net.officefloor.hq.app.setting;

/** The role a sheet gives a user name: clerk, steward or viewer. */
public record Role(String sheetId, String user, String role) {
}
package net.officefloor.hq.app.setting;

import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRole {

    private static final Set<String> ROLES = Set.of(Settings.CLERK, Settings.STEWARD, Settings.VIEWER);

    // A user name must not be blank, and the role must be clerk, steward or viewer.
    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("user") String user,
            @RequestBody RoleRequest body, Out<Role> roleOut) throws InvalidSettingException {
        String name = user == null ? "" : user.trim();
        String role = body == null || body.role() == null ? "" : body.role().trim();
        if (name.isEmpty()) {
            throw new InvalidSettingException("A user name is needed.");
        }
        if (!ROLES.contains(role)) {
            throw new InvalidSettingException("The role must be clerk, steward or viewer.");
        }
        roleOut.set(new Role(sheetId.trim(), name, role));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.variable.Val;

public class ApplyRole {
    public void apply(@Val Role role, Settings settings) {
        settings.save(role);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithRole {
    public void respond(@Val Role role, ObjectResponse<RoleResponse> response) {
        response.send(RoleResponse.from(role));
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithRoles {
    public void respond(@PathVariable("sheetId") String sheetId, Settings settings,
            ObjectResponse<List<RoleResponse>> response) {
        response.send(settings.roles(sheetId.trim()).stream().map(RoleResponse::from).toList());
    }
}
-- A sheet's settings, one value per key (clerk-limit: an amount with two decimals). A key with no
-- row, or a blank value, is not set (a clerk limit not set is no limit).
CREATE TABLE setting (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    setting_value VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key)
);
-- The role a sheet gives a user name: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    PRIMARY KEY (sheet_id, user_name)
);
-- A third role, viewer: sees everything and may change nothing. The role check is rebuilt to allow it.
CREATE TABLE sheet_role_new (
    sheet_id  VARCHAR(255) NOT NULL,
    user_name VARCHAR(255) NOT NULL,
    role      VARCHAR(16)  NOT NULL CHECK (role IN ('clerk', 'steward', 'viewer')),
    PRIMARY KEY (sheet_id, user_name)
);
INSERT INTO sheet_role_new (sheet_id, user_name, role) SELECT sheet_id, user_name, role FROM sheet_role;
DROP TABLE sheet_role;
ALTER TABLE sheet_role_new RENAME TO sheet_role;

